# name: participant_alternation_pref_sd
# description: Across-participant SD of each person's rate of choosing the more-alternating sequence (trials whose alternation counts differ); observed > null means the single-population model under-produces individual differences in alternation preference.
def test_statistic(df):
    def alts(s):
        return s.map({q: sum(q[i] != q[i - 1] for i in range(1, len(q))) for q in s.unique()})
    aa = alts(df["sequence_a"]); ab = alts(df["sequence_b"])
    m = (aa != ab).to_numpy()
    chose_more = np.where(aa.to_numpy() > ab.to_numpy(), df["chose_left"].to_numpy(), 1 - df["chose_left"].to_numpy())
    r = pd.Series(chose_more[m]).groupby(df["participant_id"].to_numpy()[m]).mean()
    return float(r.std(ddof=1)) if len(r) > 1 else 0.0

# name: high_alternation_preference
# description: Among trials where both sequences have alternation proportion >= 0.5 and differ in alternation count, the rate of choosing the more-alternating one; observed > null means humans prefer heavier alternation than the model's fitted alternation prototype allows, observed < null means the model over-rewards alternation at the high end.
def test_statistic(df):
    def pa(s):
        return s.map({q: sum(q[i] != q[i - 1] for i in range(1, len(q))) / max(len(q) - 1, 1) for q in s.unique()}).to_numpy()
    a = pa(df["sequence_a"]); b = pa(df["sequence_b"])
    m = (a >= 0.5) & (b >= 0.5) & (a != b)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()
    c = np.where(a > b, y, 1 - y)
    return float(c[m].mean())

# name: alternation_pref_drift_over_trials
# description: Rate of choosing the more-alternating sequence in the second half of each session minus the first half; positive observed vs null means preferences drift toward alternation over the session, which the static model cannot produce.
def test_statistic(df):
    def alts(s):
        return s.map({q: sum(q[i] != q[i - 1] for i in range(1, len(q))) for q in s.unique()}).to_numpy()
    aa = alts(df["sequence_a"]); ab = alts(df["sequence_b"])
    y = df["chose_left"].to_numpy()
    c = np.where(aa > ab, y, 1 - y)
    t = df["trial_index"].to_numpy()
    med = pd.Series(t).groupby(df["participant_id"].to_numpy()).transform("median").to_numpy()
    m = aa != ab
    late = m & (t > med); early = m & (t <= med)
    if late.sum() == 0 or early.sum() == 0:
        return 0.0
    return float(c[late].mean() - c[early].mean())

# name: shorter_run_rate_matched_alternations
# description: Among trials whose two sequences have equal alternation counts but different longest-run lengths, the rate of choosing the sequence with the shorter longest run; observed > null means the model under-weights long streaks as a cue to non-randomness.
def test_statistic(df):
    def feats(s):
        u = s.unique()
        alt = {}; run = {}
        for q in u:
            alt[q] = sum(q[i] != q[i - 1] for i in range(1, len(q)))
            best = cur = 1
            for i in range(1, len(q)):
                cur = cur + 1 if q[i] == q[i - 1] else 1
                best = max(best, cur)
            run[q] = best
        return s.map(alt).to_numpy(), s.map(run).to_numpy()
    aa, ra = feats(df["sequence_a"]); ab, rb = feats(df["sequence_b"])
    m = (aa == ab) & (ra != rb)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()
    c = np.where(ra < rb, y, 1 - y)
    return float(c[m].mean())

# name: balance_rate_matched_alternations
# description: Among trials whose sequences have equal alternation counts but different global |#H-#T|, the rate of choosing the globally more balanced sequence; observed > null means the model under-weights global H/T balance (its multiscale averaging dilutes it), observed < null means it over-weights it.
def test_statistic(df):
    def f(s):
        u = s.unique()
        alt = {q: sum(q[i] != q[i - 1] for i in range(1, len(q))) for q in u}
        imb = {q: abs(2 * q.count("H") - len(q)) for q in u}
        return s.map(alt).to_numpy(), s.map(imb).to_numpy()
    aa, ia = f(df["sequence_a"]); ab, ib = f(df["sequence_b"])
    m = (aa == ab) & (ia != ib)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()
    c = np.where(ia < ib, y, 1 - y)
    return float(c[m].mean())

# name: same_side_perseveration
# description: Rate at which a participant chooses the same screen side (left/right) as on their previous trial; observed > null means response-side perseveration the trial-independent model does not produce, observed < null means excess side switching.
def test_statistic(df):
    d = df.sort_values(["participant_id", "trial_index"])
    y = d["chose_left"].to_numpy(); p = d["participant_id"].to_numpy()
    same_p = p[1:] == p[:-1]
    if same_p.sum() == 0:
        return 0.5
    return float((y[1:] == y[:-1])[same_p].mean())

# name: perfect_alternation_choice_rate
# description: Rate of choosing a perfectly alternating sequence (HTHT.../THTH...) when it is paired with a non-perfectly-alternating one; observed > null means the model under-predicts acceptance of the extreme over-alternating pattern, observed < null means it over-predicts it.
def test_statistic(df):
    def perf(s):
        return s.map({q: float(all(q[i] != q[i - 1] for i in range(1, len(q)))) for q in s.unique()}).to_numpy()
    pa = perf(df["sequence_a"]); pb = perf(df["sequence_b"])
    m = pa != pb
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()
    c = np.where(pa > pb, y, 1 - y)
    return float(c[m].mean())
